test('findMaintenancePull: only a claudinite maintenance branch, only from this cycle', async () => {
  const since = Date.parse('2026-08-06T10:00:00Z');
  const gh = async (path) => {
    if (path.includes('/pulls?')) {
      return { status: 200, json: [
