test('collectFindings: annotations per job, plus any step that concluded non-green', async () => {
  const gh = async (path) => {
    if (path.includes('/jobs')) {
      return { status: 200, json: { jobs: [{ id: 5, name: 'schedule', steps: [{ name: 'Evaluate', conclusion: 'failure' }] }] } };
