  });
  assert.match(row, /oldsha1/);
  assert.match(row, /newsha2/);
  assert.match(row, /\+40\/-12 \(5f\)/);
  assert.match(row, /3m 0s/);
  assert.match(row, /yes \(\[#9\]/);
